281	@@ -0,0 +1,321 @@
282	+//! The single send fallback for a forced tool choice that the service rejects.
283	+//!
284	+//! An Anthropic model on Bedrock can reject a forced tool choice
285	+//! (`toolChoice` `any` or `tool`) with a `ValidationException`. When the
286	+//! first request carried a forced choice and the service rejects it before
287	+//! the stream starts, the provider sends the request one more time on the
288	+//! native structured-output path. The handle then records the rejection, and
289	+//! all later requests on the handle use the native path at once.
290	+//!
291	+//! This fallback does not break ADR-10 (*No silent auto-retry inside the
292	+//! loop*), for four reasons. The fallback sends a *different* request, not
293	+//! the same request again. It occurs at most once for each request. It is
294	+//! logged. It never follows a transient error (throttling, a 5xx error or a
295	+//! transport error): those errors go to the caller unchanged.
296	+//!
297	+//! The match on the error text is a weak contract. If Bedrock changes the
298	+//! text, the result is the same `ValidationException` as before this
299	+//! fallback existed. The static model-id rule still sends the known models
300	+//! on the native path from the first request.
301	+
302	+use std::future::Future;
303	+
304	+use paigasus_helikon_core::ModelError;
305	+
306	+use crate::error::SendFailure;
307	+use crate::family::ModelFamily;
308	+use crate::policy::{ForcedChoicePolicy, OutputPath};
309	+use crate::translate::PreparedConverse;
310	+
311	+/// The output of a send, with the `synthesizing` value of the request that
312	+/// was actually sent.
313	+#[derive(Debug)]
314	+pub(crate) struct Sent<T> {
315	+    /// The output of the send.
316	+    pub(crate) output: T,
317	+    /// `synthesizing` of the request that was sent.
318	+    pub(crate) synthesizing: bool,
319	+}
320	+
321	+/// Send `first`. If the service rejects its forced tool choice, send the
322	+/// request again on the native path, one time.
323	+///
324	+/// The fallback occurs only when all of these conditions are true:
325	+/// the model family is Anthropic, `first` carried a forced tool choice, and
326	+/// the failure is a rejection of that choice. `rebuild` makes the native
327	+/// request. An error from the second send goes to the caller with no
328	+/// further fallback.
329	+pub(crate) async fn send_with_fallback<T, B, S, Fut>(
330	+    policy: &ForcedChoicePolicy,
331	+    model_id: &str,
332	+    first: PreparedConverse,
333	+    rebuild: B,
334	+    mut send: S,
335	+) -> Result<Sent<T>, ModelError>
336	+where
337	+    B: FnOnce(OutputPath) -> Result<PreparedConverse, ModelError>,
338	+    S: FnMut(PreparedConverse) -> Fut,
339	+    Fut: Future<Output = Result<T, SendFailure>>,
340	+{
341	+    for n in &first.notices {
342	+        policy.note(*n, model_id);
343	+    }
344	+    let synthesizing = first.synthesizing;
345	+    let first_was_forced = first.has_forced_tool_choice();
346	+
347	+    let failure = match send(first).await {
348	+        Ok(output) => {
349	+            return Ok(Sent {
350	+                output,
351	+                synthesizing,
352	+            })
353	+        }
354	+        Err(f) => f,
355	+    };
356	+
357	+    if !(policy.family() == ModelFamily::Anthropic
358	+        && first_was_forced
359	+        && failure.forced_choice_rejected)
360	+    {
361	+        return Err(failure.error);
362	+    }
363	+
364	+    if policy.record_rejection() {
365	+        tracing::warn!(
366	+            target: "paigasus::bedrock::model",
367	+            model_id = %model_id,
368	+            "the model rejected a forced tool choice; native structured output is now in use for this handle"
369	+        );
370	+    }
371	+
372	+    let second = rebuild(OutputPath::Native)?;
373	+    for n in &second.notices {
374	+        policy.note(*n, model_id);
375	+    }
376	+    let synthesizing = second.synthesizing;
377	+    match send(second).await {
378	+        Ok(output) => Ok(Sent {
379	+            output,
380	+            synthesizing,
381	+        }),
382	+        Err(f) => Err(f.error),
383	+    }
384	+}
