446	+    /// Run `send_with_fallback` with a scripted fake send. Returns the result
447	+    /// and the wire projection of each request that the fake received.
448	+    fn drive(
449	+        policy: &ForcedChoicePolicy,
450	+        cfg: &Config,
451	+        req: &ModelRequest,
452	+        script: Vec<Result<(), SendFailure>>,
453	+    ) -> (Result<Sent<()>, ModelError>, Vec<Value>) {
454	+        let first = build_request(cfg, req, policy.path()).expect("first request");
455	+        let sent: Arc<Mutex<Vec<Value>>> = Arc::new(Mutex::new(Vec::new()));
456	+        let script = Arc::new(Mutex::new(VecDeque::from(script)));
457	+        let send = {
458	+            let sent = sent.clone();
459	+            let script = script.clone();
460	+            move |p: crate::translate::PreparedConverse| {
461	+                sent.lock().unwrap().push(to_wire_json(&p));
462	+                let next = script
463	+                    .lock()
464	+                    .unwrap()
465	+                    .pop_front()
466	+                    .expect("a send that the script does not cover");
467	+                async move { next }
468	+            }
469	+        };
470	+        let rt = tokio::runtime::Builder::new_current_thread()
471	+            .enable_all()
