 pub(crate) fn parse_retry_after_ms(headers: &Headers) -> Option<u64> {
     headers
         .get("retry-after")
         .and_then(|v| v.trim().parse::<u64>().ok())
         .map(|seconds| seconds.saturating_mul(1000))
 }
